#!/usr/bin/env python3
"""Robust minimal VNC screenshot client (no password), saves PPM.
Usage: shot.py host port out.ppm
Reads exactly ONE raw framebuffer, ignores further async updates.
"""
import socket, struct, sys

def rx(s, n):
    buf = b""
    while len(buf) < n:
        d = s.recv(n - len(buf))
        if not d:
            raise RuntimeError("connection closed")
        buf += d
    return buf

def main():
    host, port, out = sys.argv[1], int(sys.argv[2]), sys.argv[3]
    s = socket.create_connection((host, port), timeout=20)
    s.settimeout(25)
    ver = rx(s, 12)
    if not ver.startswith(b"RFB"):
        raise RuntimeError("bad banner: %r" % ver)
    s.sendall(b"RFB 003.008\n")
    auth = struct.unpack("!B", rx(s, 1))[0]
    if auth == 0:
        pass
    elif auth == 2:
        s.sendall(b"\x00" * 16)
        if struct.unpack("!I", rx(s, 4))[0] != 0:
            raise RuntimeError("VNC auth failed")
    elif auth == 6:
        s.sendall(struct.pack("!I", 0))
        n = struct.unpack("!I", rx(s, 4))[0]
        sub = rx(s, n) if n else b""
        if not sub.startswith(b"TIGHT"):
            s.close()
